import React, { useEffect, useMemo, useState } from 'react';
import { api, clearSession, getStoredUser, saveSession } from './api';
import {
  Activity, ArrowRight, BarChart3, Bot, CalendarDays, Check, ChevronDown, CircleHelp, CreditCard, Database,
  FileText, Filter, Leaf, LogOut, Menu, Plus, RefreshCw, Search, Settings2, ShieldCheck, Sparkles, Target,
  Trash2, TrendingDown, TrendingUp, Trophy, Upload, UserRound, Wallet, X, Zap
} from 'lucide-react';
import { AreaChart, Area, BarChart, Bar, CartesianGrid, Cell, PieChart, Pie, ResponsiveContainer, Tooltip, XAxis, YAxis } from 'recharts';

const categories = ['Food & groceries', 'Transportation', 'Fuel', 'Clothing', 'Electronics', 'Shopping', 'Utilities', 'Travel'];
const paymentMethods = ['UPI', 'Card', 'Wallet'];
const navItems = [
  { path: '/app', label: 'Overview', icon: Activity }, { path: '/app/transactions', label: 'Transactions', icon: CreditCard },
  { path: '/app/analytics', label: 'Carbon analytics', icon: BarChart3 }, { path: '/app/intelligence', label: 'Carbon intelligence', icon: TrendingUp },
  { path: '/app/shopping', label: 'Shopping assistant', icon: Sparkles }, { path: '/app/simulator', label: 'Purchase simulator', icon: Zap },
  { path: '/app/merchants', label: 'Green merchants', icon: Leaf }, { path: '/app/rewards', label: 'Green rewards', icon: Trophy },
  { path: '/app/goals', label: 'Sustainability goals', icon: Target }, { path: '/app/greenbot', label: 'GreenBot', icon: Bot }
];

const money = (n) => `₹${Number(n || 0).toLocaleString('en-IN', { maximumFractionDigits: 0 })}`;
const kg = (n) => `${Number(n || 0).toFixed(1)} kg`;
const formatDate = (s) => s ? new Date(`${s}T00:00:00`).toLocaleDateString('en-IN', { day: '2-digit', month: 'short', year: 'numeric' }) : '—';
const initials = (name = 'Member') => name.split(' ').map((x) => x[0]).slice(0, 2).join('').toUpperCase();

function navigate(path) { window.history.pushState({}, '', path); window.dispatchEvent(new PopStateEvent('popstate')); }
function usePath() { const [path, setPath] = useState(window.location.pathname); useEffect(() => { const fn = () => setPath(window.location.pathname); window.addEventListener('popstate', fn); return () => window.removeEventListener('popstate', fn); }, []); return path; }
function Link({ href, children, className = '', onClick }) { return <a className={className} href={href} onClick={(e) => { e.preventDefault(); onClick?.(); navigate(href); }}>{children}</a>; }
function Button({ children, variant = 'primary', className = '', ...props }) { return <button className={`btn btn-${variant} ${className}`} {...props}>{children}</button>; }
function Loading({ label = 'Loading your data' }) { return <div className="loading"><span className="spinner" />{label}</div>; }
function ErrorState({ message, retry }) { return <div className="empty-state error-state"><CircleHelp size={20} /><strong>We couldn’t load that</strong><span>{message}</span>{retry && <Button variant="secondary" onClick={retry}>Try again</Button>}</div>; }
function Logo({ compact = false }) { return <Link href="/" className={`logo ${compact ? 'logo-compact' : ''}`}><span className="logo-mark"><Leaf size={17} /></span><span>greenzaction</span></Link>; }

function Landing() {
  return <div className="landing-page">
    <header className="landing-nav container"><Logo /><div className="landing-links"><a href="#how">How it works</a><a href="#signal">Your signal</a><Link href="/login">Sign in</Link><Button onClick={() => navigate('/register')}>Create account <ArrowRight size={16} /></Button></div></header>
    <main>
      <section className="hero container"><div className="hero-copy"><div className="eyebrow"><span className="pulse-dot" /> SUSTAINABILITY, MADE PERSONAL</div><h1>Your spending has a footprint. <em>Make the next one lighter.</em></h1><p className="hero-lede">Greenzaction turns everyday digital transactions into transparent carbon estimates, useful signals and small actions that add up.</p><div className="hero-actions"><Button onClick={() => navigate('/register')}>Start your footprint <ArrowRight size={17} /></Button><a className="text-link" href="#how">See how it works <ChevronDown size={16} /></a></div><div className="hero-proof"><div><strong>8</strong><span>spending categories</span></div><div><strong>A–E</strong><span>clear carbon ratings</span></div><div><strong>100%</strong><span>your data, explained</span></div></div></div><div className="hero-visual"><div className="hero-orbit orbit-one" /><div className="hero-orbit orbit-two" /><div className="hero-score-card"><div className="mini-label">CURRENT SIGNAL</div><div className="score-ring"><div><strong>78</strong><span>/100</span></div></div><div className="score-caption"><span className="status-pill good">B · on track</span><span>+6 this month</span></div></div><div className="hero-float-card float-top"><span className="float-icon"><TrendingDown size={16} /></span><div><strong>18.4 kg</strong><small>estimated carbon</small></div></div><div className="hero-float-card float-bottom"><span className="float-icon gold"><Trophy size={16} /></span><div><strong>+240 points</strong><small>earned this season</small></div></div></div></section>
      <section id="how" className="section container"><div className="section-intro"><div className="eyebrow">THE GREenzACTION METHOD</div><h2>A clearer signal for every swipe.</h2><p>Not a guilt trip. A practical layer of context between the transaction and the choice you make next.</p></div><div className="method-grid"><MethodCard num="01" icon={CreditCard} title="Connect the moment" text="Log a simulated UPI, card or wallet purchase in seconds. No bank access. No claims of real payment processing." /><MethodCard num="02" icon={Leaf} title="Understand the estimate" text="See the category factor, calculation method and confidence behind each kg CO₂e estimate." /><MethodCard num="03" icon={Zap} title="Build your rhythm" text="Turn the signal into a Green Score, points, goals and lighter next steps that fit your real life." /></div></section>
      <section id="signal" className="signal-band"><div className="container signal-inner"><div><div className="eyebrow light">A BETTER DEFAULT</div><h2>Small choices become visible<br />before they become habits.</h2></div><div className="signal-quote"><Leaf size={20} /><p>“Estimated, explained, and yours to improve.”</p><span>— the Greenzaction promise</span></div></div></section>
    </main>
    <footer className="landing-footer container"><Logo compact /><span>Built for more intentional everyday spending.</span><span className="mono">2026 / GREenzACTION</span></footer>
  </div>;
}
function MethodCard({ num, icon: Icon, title, text }) { return <div className="method-card"><div className="method-top"><span className="mono">{num}</span><span className="method-icon"><Icon size={19} /></span></div><h3>{title}</h3><p>{text}</p><ArrowRight className="method-arrow" size={17} /></div>; }

function AuthPage({ mode = 'login', onAuth }) {
  const [form, setForm] = useState(mode === 'login' ? { email: 'demo@greenzaction.app', password: 'demo1234' } : { name: '', email: '', password: '' });
  const [error, setError] = useState(''); const [loading, setLoading] = useState(false);
  const submit = async (e) => { e.preventDefault(); setError(''); setLoading(true); try { const data = await api(`/api/auth/${mode === 'login' ? 'login' : 'register'}`, { method: 'POST', body: JSON.stringify(form) }); saveSession(data); onAuth(data.user); navigate(data.user.role === 'admin' ? '/admin' : '/app'); } catch (err) { setError(err.message); } finally { setLoading(false); } };
  return <div className="auth-page"><div className="auth-aside"><Logo /><div className="auth-aside-copy"><div className="eyebrow light">THE EVERYDAY SIGNAL</div><h1>Better context for the choices you already make.</h1><p>Greenzaction helps you see the estimated footprint of spending without turning sustainability into a spreadsheet.</p><div className="auth-stat"><strong>78</strong><span>green score<br /><small>on a sample journey</small></span></div></div><span className="mono auth-foot">EST. 2026 · TRANSPARENT BY DESIGN</span></div><div className="auth-main"><div className="auth-form-wrap"><Link href="/" className="back-link">← Back to home</Link><div className="auth-heading"><div className="eyebrow">{mode === 'login' ? 'WELCOME BACK' : 'START YOUR SIGNAL'}</div><h2>{mode === 'login' ? 'Sign in to Greenzaction' : 'Create your account'}</h2><p>{mode === 'login' ? 'Pick up where your footprint left off.' : 'Your first step toward more informed spending.'}</p></div>{error && <div className="alert error">{error}</div>}<form className="auth-form" onSubmit={submit}>{mode === 'register' && <label>Full name<input required value={form.name} onChange={(e) => setForm({ ...form, name: e.target.value })} placeholder="Aarav Mehta" /></label>}<label>Email address<input required type="email" value={form.email} onChange={(e) => setForm({ ...form, email: e.target.value })} placeholder="you@example.com" /></label><label>Password<input required minLength="8" type="password" value={form.password} onChange={(e) => setForm({ ...form, password: e.target.value })} placeholder="At least 8 characters" /></label><Button disabled={loading} className="full-width">{loading ? 'Working…' : mode === 'login' ? 'Sign in' : 'Create account'} <ArrowRight size={16} /></Button></form><p className="switch-auth">{mode === 'login' ? 'New to Greenzaction?' : 'Already have an account?'} <Link href={mode === 'login' ? '/register' : '/login'}>{mode === 'login' ? 'Create an account' : 'Sign in'}</Link></p>{mode === 'login' && <div className="demo-hint"><Sparkles size={15} /><span>Demo access is prefilled. Try <b>demo@greenzaction.app</b> / <b>demo1234</b>.</span></div>}</div></div></div>;
}

function AppShell({ user, setUser }) {
  const path = usePath(); const [mobileOpen, setMobileOpen] = useState(false); const [refresh, setRefresh] = useState(0);
  const logout = () => { clearSession(); setUser(null); navigate('/'); };
  const current = navItems.find((item) => item.path === path) || { label: path === '/admin' ? 'Admin dashboard' : path.includes('new') ? 'Add transaction' : 'Overview' };
  const content = path === '/app' ? <Dashboard refresh={refresh} user={user} onNavigate={navigate} /> : path === '/app/transactions' || path === '/app/transactions/new' ? <Transactions refresh={refresh} onRefresh={() => setRefresh((x) => x + 1)} initialNew={path.endsWith('/new')} /> : path === '/app/analytics' ? <Analytics refresh={refresh} /> : path === '/app/intelligence' ? <CarbonIntelligence refresh={refresh} /> : path === '/app/shopping' ? <ShoppingAssistant /> : path === '/app/simulator' ? <PurchaseSimulator /> : path === '/app/merchants' ? <GreenMerchants /> : path === '/app/rewards' ? <Rewards refresh={refresh} /> : path === '/app/goals' ? <Goals refresh={refresh} /> : path === '/app/greenbot' ? <GreenBot /> : path === '/app/profile' ? <Profile user={user} onUser={setUser} /> : path === '/admin' ? <Admin /> : <Dashboard refresh={refresh} user={user} onNavigate={navigate} />;
  return <div className="app-shell"><aside className={`sidebar ${mobileOpen ? 'open' : ''}`}><div className="sidebar-top"><Logo /><button className="icon-button mobile-close" onClick={() => setMobileOpen(false)}><X size={18} /></button></div><div className="workspace-chip"><span className="avatar">{initials(user.name)}</span><div><strong>{user.name}</strong><small>Personal workspace</small></div><ChevronDown size={14} /></div><nav className="side-nav"><span className="nav-overline">YOUR SIGNAL</span>{navItems.map(({ path: href, label, icon: Icon }) => <Link key={href} href={href} className={path === href ? 'active' : ''} onClick={() => setMobileOpen(false)}><Icon size={17} /><span>{label}</span>{label === 'GreenBot' && <span className="new-chip">AI</span>}</Link>)}{user.role === 'admin' && <><span className="nav-overline nav-admin-label">CONTROL ROOM</span><Link href="/admin" className={path === '/admin' ? 'active' : ''} onClick={() => setMobileOpen(false)}><ShieldCheck size={17} /><span>Admin dashboard</span></Link></>}</nav><div className="sidebar-bottom"><button className="logout-link" onClick={logout}><LogOut size={17} /><span>Sign out</span></button><div className="sidebar-meta"><span className="status-dot" /> API connected · {new Date().getFullYear()}</div></div></aside><main className="app-main"><header className="app-topbar"><button className="icon-button menu-trigger" onClick={() => setMobileOpen(true)}><Menu size={20} /></button><div><span className="breadcrumb">Greenzaction <span>/</span> {current.label}</span><h1>{current.label}</h1></div><div className="topbar-actions"><button className="icon-button" title="Refresh data" onClick={() => setRefresh((x) => x + 1)}><RefreshCw size={17} /></button><Link href="/app/greenbot" className="topbot"><GreenBotMark size={16} /> Ask GreenBot</Link><span className="avatar avatar-top">{initials(user.name)}</span></div></header><div className="app-content">{content}</div></main></div>;
}

function PageIntro({ eyebrow, title, text, action }) { return <div className="page-intro"><div><div className="eyebrow">{eyebrow}</div><h2>{title}</h2>{text && <p>{text}</p>}</div>{action}</div>; }
function StatCard({ label, value, detail, icon: Icon, accent = 'green', trend }) { return <div className={`stat-card accent-${accent}`}><div className="stat-card-top"><span>{label}</span><span className="stat-icon"><Icon size={16} /></span></div><strong>{value}</strong><div className="stat-detail">{trend && <span className={trend > 0 ? 'trend-up' : 'trend-down'}>{trend > 0 ? <TrendingUp size={13} /> : <TrendingDown size={13} />}{Math.abs(trend)}%</span>}{detail}</div></div>; }
function Dashboard({ refresh, user, onNavigate }) {
  const [data, setData] = useState(null); const [recs, setRecs] = useState([]); const [error, setError] = useState('');
  useEffect(() => { Promise.all([api('/api/dashboard'), api('/api/recommendations')]).then(([d, r]) => { setData(d); setRecs(r.items || []); }).catch((e) => setError(e.message)); }, [refresh]);
  if (error) return <ErrorState message={error} retry={() => setError('')} />; if (!data) return <Loading />;
  const chart = (data.monthly_emissions || []).map((x) => ({ ...x, month: x.month?.slice(5) || '—' }));
  return <div className="page"><div className="welcome-row"><div><div className="eyebrow">{new Date().toLocaleDateString('en-IN', { weekday: 'long', day: 'numeric', month: 'long' }).toUpperCase()}</div><h2>Good to see you, {user.name.split(' ')[0]}<span className="green-dot">.</span></h2><p>Here’s the signal behind your everyday spending.</p></div><Button onClick={() => onNavigate('/app/transactions/new')}><Plus size={17} /> Log transaction</Button></div><div className="stat-grid"><StatCard label="Total spending" value={money(data.total_spending)} detail={`${data.transaction_count} transactions`} icon={Wallet} /><StatCard label="Estimated footprint" value={kg(data.total_emissions)} detail="kg CO₂e · category estimates" icon={Leaf} accent="teal" /><StatCard label="Green Score" value={`${data.green_score}/100`} detail={`${data.rating} carbon rating`} icon={Activity} accent="gold" trend={6} /><StatCard label="Green Points" value={data.reward_points} detail={`${data.eco_percentage}% A/B-rated`} icon={Trophy} accent="purple" /></div><div className="dashboard-grid"><div className="panel footprint-panel"><div className="panel-heading"><div><span className="eyebrow">CARBON PULSE</span><h3>Estimated footprint over time</h3></div><span className="method-tag">ESTIMATE · {data.transaction_count} LOGS</span></div><div className="chart-wrap area-wrap">{chart.length ? <ResponsiveContainer width="100%" height="100%"><AreaChart data={chart}><defs><linearGradient id="carbonFill" x1="0" x2="0" y1="0" y2="1"><stop offset="0%" stopColor="#16865b" stopOpacity=".3" /><stop offset="100%" stopColor="#16865b" stopOpacity=".02" /></linearGradient></defs><CartesianGrid vertical={false} stroke="#e7eee9" /><XAxis dataKey="month" tickLine={false} axisLine={false} tick={{ fill: '#7a8a83', fontSize: 11 }} /><YAxis tickLine={false} axisLine={false} tick={{ fill: '#7a8a83', fontSize: 11 }} width={34} /><Tooltip contentStyle={{ border: '1px solid #dce8e0', borderRadius: 10, fontSize: 12 }} /><Area type="monotone" dataKey="emissions" stroke="#16865b" strokeWidth={2.5} fill="url(#carbonFill)" /></AreaChart></ResponsiveContainer> : <div className="chart-empty">Log a few transactions to see your footprint pulse.</div>}</div></div><div className="panel score-panel"><div className="panel-heading"><div><span className="eyebrow">YOUR SIGNAL</span><h3>Green Score</h3></div><span className={`status-pill ${data.rating === 'A' || data.rating === 'B' ? 'good' : 'watch'}`}>{data.rating} rating</span></div><div className="big-score"><div className="score-ring large"><div><strong>{Math.round(data.green_score)}</strong><span>/100</span></div></div><div><p>Keep your choices in the lower-impact lane to build momentum.</p><Link href="/app/analytics" className="text-link">Explore analytics <ArrowRight size={15} /></Link></div></div><div className="score-bar"><span style={{ width: `${data.green_score}%` }} /></div><div className="score-scale"><span>Needs focus</span><span>On track</span><span>Excellent</span></div></div></div><div className="lower-grid"><div className="panel category-panel"><div className="panel-heading"><div><span className="eyebrow">WHERE IT LANDS</span><h3>Emissions by category</h3></div><Link href="/app/analytics" className="text-link">Full view <ArrowRight size={14} /></Link></div>{data.category_emissions.length ? data.category_emissions.slice(0, 5).map((item, i) => <div className="category-row" key={item.category}><div className="category-label"><span className={`category-dot dot-${i}`} /><strong>{item.category}</strong><span className="mono">{kg(item.emissions)}</span></div><div className="category-bar"><span style={{ width: `${Math.min(100, (item.emissions / Math.max(data.category_emissions[0].emissions, 1)) * 100)}%` }} /></div></div>) : <div className="chart-empty">Your categories will show here.</div>}</div><div className="panel recommendation-panel"><div className="panel-heading"><div><span className="eyebrow">NEXT BEST MOVE</span><h3>Personalised guidance</h3></div><Sparkles size={18} className="sparkle" /></div>{recs.slice(0, 2).map((rec) => <div className="recommendation" key={rec.title}><span className="rec-icon"><Leaf size={15} /></span><div><strong>{rec.title}</strong><p>{rec.body}</p></div></div>)}<Link href="/app/greenbot" className="bot-prompt"><Bot size={16} /> Want a more specific answer? Ask GreenBot <ArrowRight size={14} /></Link></div></div></div>;
}

function Transactions({ refresh, onRefresh, initialNew }) {
  const [rows, setRows] = useState(null); const [filters, setFilters] = useState({ q: '', category: '', payment_method: '' }); const [modal, setModal] = useState(initialNew); const [editing, setEditing] = useState(null); const [error, setError] = useState('');
  const load = () => api(`/api/transactions?${new URLSearchParams(Object.entries(filters).filter(([, v]) => v))}`).then(setRows).catch((e) => setError(e.message));
  useEffect(() => { load(); }, [refresh, filters.q, filters.category, filters.payment_method]);
  const remove = async (id) => { if (!confirm('Delete this transaction and its reward entry?')) return; try { await api(`/api/transactions/${id}`, { method: 'DELETE' }); onRefresh(); } catch (e) { setError(e.message); } };
  const importCsv = async (e) => { const file = e.target.files?.[0]; if (!file) return; const form = new FormData(); form.append('file', file); try { const result = await api('/api/transactions/import', { method: 'POST', body: form }); alert(`${result.created} transactions imported${result.errors?.length ? `, ${result.errors.length} rows skipped` : ''}.`); onRefresh(); } catch (err) { setError(err.message); } e.target.value = ''; };
  return <div className="page"><PageIntro eyebrow="LEDGER" title="Transactions" text="A transparent record of your simulated digital spending." action={<div className="intro-actions"><label className="btn btn-secondary file-btn"><Upload size={16} /> Import CSV<input type="file" accept=".csv" onChange={importCsv} hidden /></label><Button onClick={() => { setEditing(null); setModal(true); }}><Plus size={16} /> Add transaction</Button></div>} />{error && <div className="alert error">{error}</div>}<div className="filter-bar"><div className="search-input"><Search size={16} /><input placeholder="Search merchant or description" value={filters.q} onChange={(e) => setFilters({ ...filters, q: e.target.value })} /></div><select value={filters.category} onChange={(e) => setFilters({ ...filters, category: e.target.value })}><option value="">All categories</option>{categories.map((x) => <option key={x}>{x}</option>)}</select><select value={filters.payment_method} onChange={(e) => setFilters({ ...filters, payment_method: e.target.value })}><option value="">All methods</option>{paymentMethods.map((x) => <option key={x}>{x}</option>)}</select><span className="filter-count"><Filter size={14} /> {rows?.total ?? '—'} records</span></div><div className="panel table-panel">{!rows ? <Loading /> : rows.items.length ? <div className="table-scroll"><table><thead><tr><th>Merchant</th><th>Date</th><th>Category</th><th>Method</th><th>Amount</th><th>Carbon</th><th>Rating</th><th /></tr></thead><tbody>{rows.items.map((t) => <tr key={t.id}><td><div className="merchant-cell"><span className="merchant-mark">{t.merchant?.[0]}</span><div><strong>{t.merchant}</strong><small>{t.description || 'No description'}</small></div></div></td><td className="muted">{formatDate(t.date)}</td><td><span className="soft-tag">{t.category}</span></td><td className="mono muted">{t.payment_method}</td><td className="mono">{money(t.amount)}</td><td><strong>{kg(t.emissions_kg)}</strong><small className="table-sub">estimate</small></td><td><span className={`rating rating-${t.rating}`}>{t.rating}</span></td><td><div className="row-actions"><button onClick={() => { setEditing(t); setModal(true); }} title="Edit"><Settings2 size={15} /></button><button onClick={() => remove(t.id)} title="Delete"><Trash2 size={15} /></button></div></td></tr>)}</tbody></table></div> : <div className="empty-state"><Database size={24} /><strong>No transactions match</strong><span>Log or import your first purchase to start seeing the signal.</span><Button onClick={() => setModal(true)}><Plus size={16} /> Add transaction</Button></div>}</div>{modal && <TransactionModal transaction={editing} onClose={() => { setModal(false); setEditing(null); }} onSaved={() => { setModal(false); setEditing(null); onRefresh(); }} />}</div>;
}
function TransactionModal({ transaction, onClose, onSaved }) {
  const [form, setForm] = useState(transaction || { merchant: '', amount: '', date: new Date().toISOString().slice(0, 10), category: 'Food & groceries', payment_method: 'UPI', description: '', quantity: 1, unit: 'unit' }); const [error, setError] = useState(''); const [loading, setLoading] = useState(false);
  const submit = async (e) => { e.preventDefault(); setLoading(true); try { await api(transaction ? `/api/transactions/${transaction.id}` : '/api/transactions', { method: transaction ? 'PUT' : 'POST', body: JSON.stringify({ ...form, amount: Number(form.amount), quantity: Number(form.quantity || 1) }) }); onSaved(); } catch (err) { setError(err.message); } finally { setLoading(false); } };
  return <div className="modal-backdrop"><div className="modal"><div className="modal-header"><div><div className="eyebrow">{transaction ? 'UPDATE RECORD' : 'NEW RECORD'}</div><h3>{transaction ? 'Edit transaction' : 'Log a transaction'}</h3></div><button className="icon-button" onClick={onClose}><X size={18} /></button></div><p className="modal-note">This simulates a digital payment. It does not move money or connect to a bank.</p>{error && <div className="alert error">{error}</div>}<form className="form-grid" onSubmit={submit}><label className="span-2">Merchant name<input required value={form.merchant} onChange={(e) => setForm({ ...form, merchant: e.target.value })} placeholder="e.g. Green Basket" /></label><label>Amount (₹)<input required type="number" min="1" value={form.amount} onChange={(e) => setForm({ ...form, amount: e.target.value })} placeholder="680" /></label><label>Date<input required type="date" value={form.date} onChange={(e) => setForm({ ...form, date: e.target.value })} /></label><label>Quantity<input required type="number" min="0.1" step="0.1" value={form.quantity || 1} onChange={(e) => setForm({ ...form, quantity: e.target.value })} /></label><label>Unit<input value={form.unit || 'unit'} onChange={(e) => setForm({ ...form, unit: e.target.value })} placeholder="unit, device, journey" /></label><label>Category<select value={form.category} onChange={(e) => setForm({ ...form, category: e.target.value })}>{categories.map((x) => <option key={x}>{x}</option>)}</select></label><label>Payment method<select value={form.payment_method} onChange={(e) => setForm({ ...form, payment_method: e.target.value })}>{paymentMethods.map((x) => <option key={x}>{x}</option>)}</select></label><label className="span-2">Product description <span className="optional">optional</span><input value={form.description} onChange={(e) => setForm({ ...form, description: e.target.value })} placeholder="What did this purchase represent?" /></label><div className="modal-actions span-2"><Button type="button" variant="secondary" onClick={onClose}>Cancel</Button><Button disabled={loading}>{loading ? 'Saving…' : transaction ? 'Save changes' : 'Calculate & save'} <ArrowRight size={15} /></Button></div></form></div></div>;
}

function Analytics({ refresh }) {
  const [data, setData] = useState(null); const [error, setError] = useState(''); useEffect(() => { api('/api/analytics').then(setData).catch((e) => setError(e.message)); }, [refresh]); if (error) return <ErrorState message={error} />; if (!data) return <Loading />;
  const colors = ['#16865b', '#2ea975', '#73bd91', '#d6a941', '#9b8062', '#7b9b8d'];
  return <div className="page"><PageIntro eyebrow="MEASURE WITH CONTEXT" title="Carbon analytics" text="Understand which categories shape your estimate, and why." action={<span className="method-tag"><FileText size={13} /> METHODOLOGY AVAILABLE</span>} /><div className="analytics-top"><div className="panel methodology"><div className="panel-heading"><div><span className="eyebrow">HOW IT’S CALCULATED</span><h3>Estimate, not false precision.</h3></div><Leaf size={20} className="sparkle" /></div><p>{data.methodology}</p><div className="formula"><span>ACTIVITY DATA</span><strong>×</strong><span>EMISSION FACTOR</span><strong>=</strong><span className="formula-result">KG CO₂e</span></div><div className="confidence-row"><span className="status-pill good">Transparent method</span><span>Every calculation stores a source and confidence level.</span></div></div><div className="panel analytics-score"><span className="eyebrow">CURRENT GREEN SCORE</span><div className="analytics-score-row"><strong>{Math.round(data.metrics.green_score)}</strong><span>/100</span><span className={`rating rating-${data.metrics.rating}`}>{data.metrics.rating}</span></div><p>Across {data.metrics.transaction_count} logged purchases</p></div></div><div className="analytics-charts"><div className="panel chart-panel"><div className="panel-heading"><div><span className="eyebrow">CATEGORY MIX</span><h3>Where the estimate lands</h3></div></div><div className="donut-layout"><div className="donut"><ResponsiveContainer width="100%" height="100%"><PieChart><Pie data={data.metrics.category_emissions} dataKey="emissions" nameKey="category" innerRadius={58} outerRadius={86} paddingAngle={3}>{data.metrics.category_emissions.map((_, i) => <Cell key={i} fill={colors[i % colors.length]} />)}</Pie><Tooltip /></PieChart></ResponsiveContainer><div className="donut-center"><strong>{kg(data.metrics.total_emissions)}</strong><span>total</span></div></div><div className="legend-list">{data.metrics.category_emissions.map((x, i) => <div key={x.category}><span style={{ background: colors[i % colors.length] }} /> <b>{x.category}</b><span className="mono">{kg(x.emissions)}</span></div>)}</div></div></div><div className="panel chart-panel"><div className="panel-heading"><div><span className="eyebrow">MONTHLY VIEW</span><h3>Footprint rhythm</h3></div></div><div className="chart-wrap bar-wrap"><ResponsiveContainer width="100%" height="100%"><BarChart data={data.metrics.monthly_emissions}><CartesianGrid vertical={false} stroke="#e7eee9" /><XAxis dataKey="month" tickLine={false} axisLine={false} tick={{ fill: '#7a8a83', fontSize: 11 }} /><YAxis tickLine={false} axisLine={false} tick={{ fill: '#7a8a83', fontSize: 11 }} /><Tooltip /><Bar dataKey="emissions" fill="#16865b" radius={[5, 5, 0, 0]} /></BarChart></ResponsiveContainer></div></div></div><div className="panel insights-panel"><div className="panel-heading"><div><span className="eyebrow">READ THE SIGNAL</span><h3>Category insights</h3></div></div><div className="insights-grid">{data.insights.map((x, i) => <div className="insight-card" key={x.category}><span className="insight-number">0{i + 1}</span><strong>{x.category}</strong><span>{x.count} {x.count === 1 ? 'purchase' : 'purchases'} · {kg(x.emissions)}</span><small>{money(x.spend)} spent</small></div>)}</div></div></div>;
}

function Rewards({ refresh }) { const [data, setData] = useState(null); useEffect(() => { api('/api/rewards').then(setData); }, [refresh]); if (!data) return <Loading />; return <div className="page"><PageIntro eyebrow="MAKE IT COUNT" title="Green rewards" text="Every lower-carbon choice is a small vote for the world you want to live in." action={<div className="points-total"><span>YOUR BALANCE</span><strong>{data.points}</strong><small>GREEN POINTS</small></div>} /><div className="badges-grid">{data.badges.map((badge) => <div className={`badge-card ${badge.earned ? 'earned' : ''}`} key={badge.id}><div className="badge-icon"><Trophy size={22} /></div><div><span className="eyebrow">{badge.earned ? 'UNLOCKED' : 'IN PROGRESS'}</span><h3>{badge.name}</h3><p>{badge.description}</p></div>{badge.earned && <Check className="badge-check" size={18} />}</div>)}</div><div className="panel reward-ledger"><div className="panel-heading"><div><span className="eyebrow">REWARD LEDGER</span><h3>Points, with receipts</h3></div><span className="method-tag">DUPLICATES PREVENTED</span></div>{data.ledger.length ? <div className="ledger-list">{data.ledger.map((x) => <div className="ledger-row" key={x.id}><span className="ledger-icon"><Leaf size={15} /></span><div><strong>{x.reason}</strong><small>{formatDate(x.created_at?.slice(0, 10))} · linked to a transaction</small></div><strong className="ledger-points">+{x.points}</strong></div>)}</div> : <div className="empty-state"><Trophy size={22} /><strong>Your ledger is waiting</strong><span>A or B-rated purchases earn Green Points automatically.</span></div>}</div></div>; }

function Goals({ refresh }) { const [goals, setGoals] = useState(null); const [title, setTitle] = useState(''); const [error, setError] = useState(''); const load = () => api('/api/goals').then((x) => setGoals(x.items)); useEffect(() => { load(); }, [refresh]); const add = async (e) => { e.preventDefault(); if (!title.trim()) return; try { await api('/api/goals', { method: 'POST', body: JSON.stringify({ title, target: 'Keep the next choice lighter' }) }); setTitle(''); load(); } catch (e) { setError(e.message); } }; const progress = async (goal) => { await api(`/api/goals/${goal.id}`, { method: 'PUT', body: JSON.stringify({ progress: Math.min(100, goal.progress + 25) }) }); load(); }; if (!goals) return <Loading />; return <div className="page"><PageIntro eyebrow="TURN INTENT INTO RHYTHM" title="Sustainability goals" text="A few concrete commitments are easier to keep than a perfect score." /><div className="goal-layout"><div className="panel goal-create"><div className="eyebrow">NEW COMMITMENT</div><h3>What would you like to make lighter?</h3><form onSubmit={add}><input value={title} onChange={(e) => setTitle(e.target.value)} placeholder="e.g. Take public transport twice a week" /><Button>Add goal <Plus size={15} /></Button></form>{error && <div className="alert error">{error}</div>}<div className="goal-note"><Target size={17} /><span>Goals are yours to define. Progress is deliberately simple: keep the next action visible.</span></div></div><div className="goals-list">{goals.length ? goals.map((goal) => <div className="panel goal-card" key={goal.id}><div className="goal-card-top"><span className="goal-icon"><Target size={17} /></span><span className={`status-pill ${goal.status === 'complete' ? 'good' : 'watch'}`}>{goal.status}</span></div><h3>{goal.title}</h3><p>{goal.target}</p><div className="goal-progress"><span style={{ width: `${goal.progress}%` }} /></div><div className="goal-bottom"><span className="mono">{goal.progress}% complete</span>{goal.progress < 100 && <button onClick={() => progress(goal)}>Mark next step <ArrowRight size={14} /></button>}</div></div>) : <div className="panel empty-state"><Target size={24} /><strong>No goals yet</strong><span>Create one small commitment to give your signal direction.</span></div>}</div></div></div>; }

function GreenBot() { const [messages, setMessages] = useState([{ role: 'bot', text: 'I’m GreenBot. Ask me about your footprint, your top category, your score, spending this month, or how to make the next choice lighter.' }]); const [question, setQuestion] = useState(''); const [loading, setLoading] = useState(false); const ask = async (q = question) => { if (!q.trim() || loading) return; setMessages((m) => [...m, { role: 'user', text: q }]); setQuestion(''); setLoading(true); try { const x = await api('/api/chatbot', { method: 'POST', body: JSON.stringify({ question: q }) }); setMessages((m) => [...m, { role: 'bot', text: x.answer }]); } catch (e) { setMessages((m) => [...m, { role: 'bot', text: e.message }]); } finally { setLoading(false); } }; const prompts = ['Which purchase generated the highest emissions?', 'What is my predicted carbon footprint next month?', 'How can I reduce my carbon budget?', 'Which products should I replace?']; return <div className="page"><PageIntro eyebrow="YOUR SUSTAINABILITY ASSISTANT" title="GreenBot" text="Answers are grounded in the transaction records connected to your account." action={<span className="bot-online"><span className="status-dot" /> ONLINE</span>} /><div className="bot-layout"><div className="panel chat-panel"><div className="chat-head"><span className="bot-avatar"><GreenBotMark size={23} /></span><div><strong>GreenBot</strong><small>Data-backed sustainability guidance</small></div><span className="method-tag">NO INVENTED STATS</span></div><div className="chat-messages">{messages.map((m, i) => <div className={`chat-message ${m.role}`} key={i}><div className="message-bubble">{m.text}</div></div>)}{loading && <div className="chat-message bot"><div className="message-bubble typing"><span /><span /><span /></div></div>}</div><div className="quick-prompts">{prompts.map((p) => <button key={p} onClick={() => ask(p)}>{p}</button>)}</div><form className="chat-input" onSubmit={(e) => { e.preventDefault(); ask(); }}><input value={question} onChange={(e) => setQuestion(e.target.value)} placeholder="Ask a question about your signal…" /><button><ArrowRight size={17} /></button></form></div><div className="panel bot-aside"><div className="eyebrow">WHAT I CAN SEE</div><h3>Only your authenticated data.</h3><p>GreenBot reads your current transaction totals, categories, estimated emissions, score and rewards. It will tell you when a number is an estimate.</p><div className="bot-capability"><Check size={15} /> Current footprint</div><div className="bot-capability"><Check size={15} /> Highest-impact category</div><div className="bot-capability"><Check size={15} /> Score and points</div><div className="bot-capability"><Check size={15} /> Practical next steps</div></div></div></div>; }

function Profile({ user, onUser }) { const [name, setName] = useState(user.name); const [password, setPassword] = useState(''); const [saved, setSaved] = useState(false); const save = async (e) => { e.preventDefault(); const x = await api('/api/profile', { method: 'PUT', body: JSON.stringify({ name, password }) }); onUser(x.user); localStorage.setItem('greenzaction_user', JSON.stringify(x.user)); setPassword(''); setSaved(true); setTimeout(() => setSaved(false), 2500); }; return <div className="page"><PageIntro eyebrow="YOUR SPACE" title="Profile & settings" text="Keep your identity and access details current." /><div className="profile-layout"><div className="panel profile-card"><div className="profile-avatar">{initials(user.name)}</div><h3>{user.name}</h3><p>{user.email}</p><span className="status-pill good">{user.role === 'admin' ? 'Admin access' : 'Personal account'}</span><div className="profile-meta"><span>Member since</span><strong>{formatDate(user.created_at?.slice(0, 10))}</strong></div></div><div className="panel settings-panel"><div className="panel-heading"><div><span className="eyebrow">ACCOUNT DETAILS</span><h3>Edit profile</h3></div><UserRound size={19} /></div><form onSubmit={save} className="settings-form"><label>Display name<input value={name} onChange={(e) => setName(e.target.value)} /></label><label>Email address<input value={user.email} disabled /></label><label>New password <span className="optional">leave blank to keep current</span><input type="password" minLength="8" value={password} onChange={(e) => setPassword(e.target.value)} /></label><div>{saved && <span className="saved-message"><Check size={15} /> Saved</span>}<Button>Save changes <ArrowRight size={15} /></Button></div></form></div></div></div>; }

function Admin() { const [data, setData] = useState(null); const [factors, setFactors] = useState(null); const [error, setError] = useState(''); const [saved, setSaved] = useState(''); useEffect(() => { Promise.all([api('/api/admin/overview'), api('/api/admin/factors')]).then(([overview, factorData]) => { setData(overview); setFactors(factorData.items); }).catch((e) => setError(e.message)); }, []); const saveFactor = async (factor) => { try { await api(`/api/admin/factors/${encodeURIComponent(factor.category)}`, { method: 'PUT', body: JSON.stringify({ factor: Number(factor.factor), proxy: Number(factor.proxy), confidence: factor.confidence }) }); setSaved(factor.category); setTimeout(() => setSaved(''), 1800); } catch (e) { setError(e.message); } }; if (error) return <ErrorState message={error} />; if (!data || !factors) return <Loading />; return <div className="page"><PageIntro eyebrow="CONTROL ROOM" title="Admin dashboard" text="A system view of users, transactions and the estimation layer." action={<span className="status-pill good"><ShieldCheck size={14} /> ADMIN AUTHORIZED</span>} /><div className="stat-grid admin-stat-grid"><StatCard label="Registered users" value={data.users} detail="all account roles" icon={UserRound} /><StatCard label="Transactions" value={data.transactions} detail="all simulated payments" icon={CreditCard} accent="teal" /><StatCard label="Estimated emissions" value={kg(data.emissions)} detail="across the system" icon={Leaf} accent="gold" /><StatCard label="Green Points issued" value={data.reward_points} detail="reward ledger total" icon={Trophy} accent="purple" /></div><div className="admin-grid"><div className="panel table-panel"><div className="panel-heading"><div><span className="eyebrow">RECENT USERS</span><h3>Registered accounts</h3></div><span className="method-tag">PRIVACY-SAFE VIEW</span></div><div className="user-list">{data.recent_users.map((u) => <div className="user-row" key={u.id}><span className="avatar">{initials(u.name)}</span><div><strong>{u.name}</strong><small>{u.email}</small></div><span className={`status-pill ${u.role === 'admin' ? 'watch' : 'good'}`}>{u.role}</span></div>)}</div></div><div className="panel admin-category"><div className="panel-heading"><div><span className="eyebrow">CATEGORY MANAGEMENT</span><h3>System categories</h3></div><Settings2 size={18} /></div>{data.categories.map((x) => <div className="admin-category-row" key={x.category}><div><strong>{x.category}</strong><small>{x.transactions} transactions · {kg(x.emissions)}</small></div><span className="mono">active</span></div>)}</div></div><div className="panel factor-panel"><div className="panel-heading"><div><span className="eyebrow">EMISSION FACTOR MANAGEMENT</span><h3>Reference factors and confidence</h3></div><span className="method-tag">ADMIN ONLY · SAVES TO STORE</span></div><div className="factor-table">{factors.map((factor) => <div className="factor-row" key={factor.category}><strong>{factor.category}</strong><label>Factor<input type="number" step="0.01" value={factor.factor} onChange={(e) => setFactors(factors.map((x) => x.category === factor.category ? { ...x, factor: e.target.value } : x))} /></label><label>Proxy<input type="number" step="0.1" value={factor.proxy} onChange={(e) => setFactors(factors.map((x) => x.category === factor.category ? { ...x, proxy: e.target.value } : x))} /></label><span className="mono factor-confidence">{factor.confidence}</span><Button variant="secondary" onClick={() => saveFactor(factor)}>{saved === factor.category ? <Check size={14} /> : 'Save'}</Button></div>)}</div></div></div>; }

export default function App() { const path = usePath(); const [user, setUser] = useState(getStoredUser()); useEffect(() => { if (localStorage.getItem('greenzaction_token')) api('/api/auth/me').then((x) => { setUser(x.user); localStorage.setItem('greenzaction_user', JSON.stringify(x.user)); }).catch(() => { clearSession(); setUser(null); }); }, []); if (path === '/' && !user) return <Landing />; if (path === '/login' && !user) return <AuthPage mode="login" onAuth={setUser} />; if (path === '/register' && !user) return <AuthPage mode="register" onAuth={setUser} />; if (!user) { navigate('/'); return null; } return <AppShell user={user} setUser={setUser} />; }

function GreenBotMark({ size = 22 }) { return <svg className="greenbot-mark" width={size} height={size} viewBox="0 0 32 32" aria-label="GreenBot mark"><defs><linearGradient id="botOrbital" x1="0" x2="1" y1="0" y2="1"><stop stopColor="#9bf0bd" /><stop offset="1" stopColor="#20a56d" /></linearGradient></defs><circle cx="16" cy="16" r="13" fill="#123e30" stroke="url(#botOrbital)" strokeWidth="1.5" /><path d="M9.5 17.5c3.8-7.2 9.9-8.2 13-8.3-1.1 3.1-3.8 8.4-10.3 10.2" fill="none" stroke="#9bf0bd" strokeWidth="1.7" strokeLinecap="round" /><path d="M10.2 22.1c4.7-1.3 8.7-3.4 12.1-8.4" fill="none" stroke="#4ed18c" strokeWidth="1.5" strokeLinecap="round" /><circle cx="23.7" cy="10.1" r="2" fill="#f1d67c" /></svg>; }

function CarbonIntelligence({ refresh }) { const [data, setData] = useState(null); const [limit, setLimit] = useState('50'); const [saved, setSaved] = useState(false); const [error, setError] = useState(''); const load = () => api('/api/advanced/overview').then(setData).catch((e) => setError(e.message)); useEffect(() => { load(); }, [refresh]); const saveBudget = async (e) => { e.preventDefault(); try { await api('/api/budget', { method: 'PUT', body: JSON.stringify({ monthly_limit_kg: Number(limit) }) }); setSaved(true); load(); setTimeout(() => setSaved(false), 2000); } catch (e) { setError(e.message); } }; if (error) return <ErrorState message={error} retry={() => { setError(''); load(); }} />; if (!data) return <Loading />; const prediction = data.prediction; return <div className="page"><PageIntro eyebrow="THE NEXT SIGNAL" title="Carbon intelligence" text="Forecasts, budgets and behavioural patterns built from your authenticated transaction history." action={<span className="method-tag"><TrendingUp size={13} /> MODEL-ASSISTED</span>} /><div className="intelligence-grid"><div className="panel prediction-card"><div className="panel-heading"><div><span className="eyebrow">NEXT MONTH FORECAST</span><h3>{prediction.status === 'ready' ? `${prediction.next_month_kg} kg CO₂e predicted` : 'Forecast needs more history'}</h3></div><span className="confidence-chip">{prediction.confidence || 0}% confidence</span></div><p>{prediction.status === 'ready' ? `The model sees ${prediction.rising_categories?.length ? prediction.rising_categories.join(', ') : 'no clear rising category'} as the main pattern to watch.` : prediction.message}</p>{prediction.history?.length ? <div className="chart-wrap intelligence-chart"><ResponsiveContainer width="100%" height="100%"><AreaChart data={prediction.history}><defs><linearGradient id="forecastFill" x1="0" x2="0" y1="0" y2="1"><stop offset="0%" stopColor="#51bb83" stopOpacity=".3" /><stop offset="100%" stopColor="#51bb83" stopOpacity=".02" /></linearGradient></defs><CartesianGrid vertical={false} stroke="#e7eee9" /><XAxis dataKey="month" tickLine={false} axisLine={false} tick={{ fill: '#7a8a83', fontSize: 11 }} /><YAxis tickLine={false} axisLine={false} tick={{ fill: '#7a8a83', fontSize: 11 }} /><Tooltip /><Area dataKey="emissions" type="monotone" stroke="#16865b" fill="url(#forecastFill)" strokeWidth={2} /></AreaChart></ResponsiveContainer></div> : null}<div className="model-metrics"><span>MAE <b>{prediction.mae ?? '—'}</b></span><span>RMSE <b>{prediction.rmse ?? '—'}</b></span><span>MODEL <b>{prediction.status === 'ready' ? 'Linear trend' : 'Waiting'}</b></span></div></div><div className={`panel budget-card ${data.budget.alert ? 'budget-alert' : ''}`}><div className="panel-heading"><div><span className="eyebrow">PERSONAL CARBON BUDGET</span><h3>{data.budget.remaining_kg.toFixed(1)} kg remaining</h3></div><Target size={19} /></div><div className="budget-meter"><span style={{ width: `${Math.min(100, data.budget.utilization)}%` }} /></div><div className="budget-numbers"><span>{data.budget.consumed_kg} kg used</span><strong>{data.budget.utilization}%</strong><span>{data.budget.monthly_limit_kg} kg target</span></div><p>{data.budget.alert ? 'You are approaching your limit. GreenBot can help find lower-carbon swaps.' : 'Your target is a guardrail, not a judgement. Adjust it as your life changes.'}</p><form className="budget-form" onSubmit={saveBudget}><input type="number" min="1" step="1" value={limit} onChange={(e) => setLimit(e.target.value)} /><Button variant="secondary">Set monthly limit</Button>{saved && <span className="saved-message"><Check size={14} /> Saved</span>}</form></div></div><div className="panel report-panel"><div className="panel-heading"><div><span className="eyebrow">MONTHLY SUSTAINABILITY REPORT</span><h3>A concise read on your direction</h3></div><Sparkles size={18} className="sparkle" /></div><p>{data.monthly_report}</p><div className="report-highlights"><div><span className="mono">POTENTIAL SAVINGS</span><strong>{data.potential_savings_kg.toFixed(1)} kg</strong><small>by choosing a lower-impact comparable product</small></div><div><span className="mono">RISING CATEGORIES</span><strong>{prediction.rising_categories?.length || 0}</strong><small>{prediction.rising_categories?.join(', ') || 'No rising pattern yet'}</small></div></div></div><div className="challenge-panel"><div className="panel-heading"><div><span className="eyebrow">DYNAMIC CHALLENGES</span><h3>Turn the forecast into action</h3></div></div><div className="challenge-grid">{data.challenges.map((challenge) => <div className={`challenge-card ${challenge.complete ? 'complete' : ''}`} key={challenge.id}><div className="challenge-head"><span className="challenge-icon">{challenge.complete ? <Check size={16} /> : <Target size={16} />}</span><span className="mono">+{challenge.reward} pts</span></div><strong>{challenge.title}</strong><p>{challenge.description}</p><div className="challenge-progress"><span style={{ width: `${Math.min(100, challenge.progress / challenge.target * 100)}%` }} /></div><small>{challenge.progress}/{challenge.target} complete</small></div>)}</div></div></div>; }

function ShoppingAssistant() { const [query, setQuery] = useState('laptop'); const [items, setItems] = useState([]); const [error, setError] = useState(''); const search = async (e) => { e?.preventDefault(); try { const x = await api(`/api/products?q=${encodeURIComponent(query)}`); setItems(x.items); } catch (e) { setError(e.message); } }; useEffect(() => { search(); }, []); return <div className="page"><PageIntro eyebrow="SHOP WITH CONTEXT" title="Sustainable shopping assistant" text="Search product profiles, compare lifecycle estimates, and understand why a lower-impact alternative is recommended." action={<span className="method-tag"><Sparkles size={13} /> AI-READY</span>} />{error && <div className="alert error">{error}</div>}<form className="assistant-search" onSubmit={search}><Search size={17} /><input value={query} onChange={(e) => setQuery(e.target.value)} placeholder="Search laptop, refill, metro…" /><Button>Search products <ArrowRight size={15} /></Button></form><div className="product-grid">{items.length ? items.map((item) => <div className="panel product-card" key={item.id}><div className="product-orb"><Leaf size={20} /></div><span className="eyebrow">{item.category.toUpperCase()}</span><h3>{item.name}</h3><div className="product-carbon"><strong>{item.emissions_kg.toFixed(1)} kg</strong><span>estimated lifecycle</span></div><div className="product-facts"><span>Repairability <b>{item.repairability}/100</b></span><span>Efficiency <b>{item.energy_efficiency}/100</b></span>{item.refurbished && <span className="status-pill good">Refurbished</span>}</div><p>{item.reason}</p><Button variant="secondary" onClick={() => navigate(`/app/simulator?query=${encodeURIComponent(item.category === 'Electronics' ? 'laptop' : item.name)}`)}>Compare alternatives <ArrowRight size={14} /></Button></div>) : <div className="panel empty-state"><Sparkles size={24} /><strong>No product profiles found</strong><span>Try a broader search term.</span></div>}</div></div>; }

function PurchaseSimulator() { const initial = new URLSearchParams(window.location.search).get('query') || 'laptop'; const [query, setQuery] = useState(initial); const [quantity, setQuantity] = useState(1); const [items, setItems] = useState([]); const [loading, setLoading] = useState(false); const compare = async (e) => { e?.preventDefault(); setLoading(true); try { const x = await api('/api/shopping/compare', { method: 'POST', body: JSON.stringify({ query, quantity }) }); setItems(x.items); } finally { setLoading(false); } }; useEffect(() => { compare(); }, []); const baseline = items.length ? Math.max(...items.map((x) => x.emissions_kg)) : 0; return <div className="page"><PageIntro eyebrow="BEFORE YOU BUY" title="Green purchase simulator" text="Compare consistent lifecycle boundaries before a purchase. The most sustainable option is shown with its avoided emissions." action={<span className="method-tag"><Zap size={13} /> SCENARIO MODE</span>} /><div className="simulator-controls"><form onSubmit={compare}><label>Product or category<input value={query} onChange={(e) => setQuery(e.target.value)} placeholder="e.g. laptop" /></label><label>Quantity<input type="number" min="1" value={quantity} onChange={(e) => setQuantity(e.target.value)} /></label><Button disabled={loading}>{loading ? 'Comparing…' : 'Compare options'} <ArrowRight size={15} /></Button></form></div>{items.length ? <><div className="simulator-callout"><Leaf size={19} /><div><strong>{items[0].name} is the lowest-estimate option.</strong><span>Choosing it instead of the highest-estimate option could avoid {Math.max(0, baseline - items[0].emissions_kg).toFixed(1)} kg CO₂e in this scenario.</span></div></div><div className="compare-grid">{items.map((item, i) => <div className={`panel compare-card ${i === 0 ? 'recommended' : ''}`} key={item.id}>{i === 0 && <span className="recommended-tag">RECOMMENDED</span>}<div className="compare-top"><span className="product-orb"><Leaf size={18} /></span><span className="mono">{item.refurbished ? 'REFURBISHED' : 'NEW OPTION'}</span></div><h3>{item.name}</h3><div className="compare-emissions"><strong>{item.emissions_kg.toFixed(1)}</strong><span>kg CO₂e</span></div><div className="lifecycle-list">{Object.entries(item.lifecycle).map(([key, value]) => <span key={key}><i style={{ width: `${Math.min(100, value / Math.max(item.emissions_kg, 1) * 100)}%` }} />{key} <b>{value}</b></span>)}</div><div className="savings-line">{item.savings_kg.toFixed(1)} kg avoided vs highest estimate</div><p>{item.reason}</p></div>)}</div></> : <Loading />}</div>; }

function GreenMerchants() { const [query, setQuery] = useState(''); const [items, setItems] = useState([]); const [error, setError] = useState(''); const load = () => api(`/api/merchants?q=${encodeURIComponent(query)}`).then((x) => setItems(x.items)).catch((e) => setError(e.message)); useEffect(() => { load(); }, []); return <div className="page"><PageIntro eyebrow="DISCOVER BETTER DEFAULTS" title="Green merchants" text="A curated discovery layer for refill, repair, transit and refurbished choices. Verify availability before visiting." action={<span className="method-tag"><Leaf size={13} /> CURATED DIRECTORY</span>} />{error && <div className="alert error">{error}</div>}<form className="assistant-search merchant-search" onSubmit={(e) => { e.preventDefault(); load(); }}><Search size={17} /><input value={query} onChange={(e) => setQuery(e.target.value)} placeholder="Search city, merchant type, or signal" /><Button>Find merchants <ArrowRight size={15} /></Button></form><div className="merchant-grid">{items.map((merchant) => <div className="panel merchant-card" key={merchant.id}><div className="merchant-card-top"><span className="merchant-mark large"><Leaf size={17} /></span><span className="status-pill good">{merchant.city}</span></div><h3>{merchant.name}</h3><span className="eyebrow">{merchant.type}</span><p>{merchant.signal}</p><div className="merchant-tags">{merchant.tags.map((tag) => <span key={tag}>{tag}</span>)}</div><a className="text-link" href={merchant.source_url} target="_blank" rel="noreferrer">View source <ArrowRight size={14} /></a></div>)}</div></div>; }
